func (syncgoCtx *Context) cheapComputableIndex(width int64) bool {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	switch syncgoCtx.Typecheck.IR.Base.Ctxt.Arch.Family {
	// MIPS does not have R+R addressing
	// Arm64 may lack ability to generate this code in our assembler,
	// but the architecture supports it.
	case sys.Loong64, sys.PPC64, sys.S390X:
		return width == 1
	case sys.AMD64, sys.I386, sys.ARM64, sys.ARM:
		switch width {
		case 1, 2, 4, 8:
			return true
		}
	}
	return false
}

