// rangeAssign returns "n.Key = key".
func (syncgoCtx *Context) rangeAssign(n *ir.RangeStmt, key ir.Node) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	key = syncgoCtx.rangeConvert(n, n.Key.Type(), key, n.KeyTypeWord, n.KeySrcRType)
	return syncgoCtx.Typecheck.IR.NewAssignStmt(n.Pos(), n.Key, key)
}

// rangeAssign2 returns "n.Key, n.Value = key, value".
func (syncgoCtx *Context) rangeAssign2(n *ir.RangeStmt, key, value ir.Node) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	// Use OAS2 to correctly handle assignments
	// of the form "v1, a[v1] = range".
	key = syncgoCtx.rangeConvert(n, n.Key.Type(), key, n.KeyTypeWord, n.KeySrcRType)
	value = syncgoCtx.rangeConvert(n, n.Value.Type(), value, n.ValueTypeWord, n.ValueSrcRType)
	return syncgoCtx.Typecheck.IR.NewAssignListStmt(n.Pos(), ir.OAS2, []ir.Node{n.Key, n.Value}, []ir.Node{key, value})
}

// rangeConvert returns src, converted to dst if necessary. If a
// conversion is necessary, then typeWord and srcRType are copied to
// their respective ConvExpr fields.
func (syncgoCtx *Context) rangeConvert(nrange *ir.RangeStmt, dst *types.Type, src, typeWord, srcRType ir.Node) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	src = syncgoCtx.Typecheck.Expr(src)
	if dst.Kind() == types.TBLANK || syncgoCtx.Typecheck.IR.Types.Identical(dst, src.Type()) {
		return src
	}

	n := syncgoCtx.Typecheck.IR.NewConvExpr(nrange.Pos(), ir.OCONV, dst, src)
	n.TypeWord = typeWord
	n.SrcRType = srcRType
	return syncgoCtx.Typecheck.Expr(n)
}

