//	}
//
// where == for keys of map m is reflexive.
func (syncgoCtx *Context) isMapClear(n *ir.RangeStmt) bool {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	if syncgoCtx.Typecheck.IR.Base.Flag.N != 0 || syncgoCtx.Typecheck.IR.Base.Flag.Cfg.Instrumenting {
		return false
	}

	t := n.X.Type()
	if n.Op() != ir.ORANGE || t.Kind() != types.TMAP || n.Key == nil || n.Value != nil {
		return false
	}

	k := n.Key
	// Require k to be a new variable name.
	if !syncgoCtx.Typecheck.IR.DeclaredBy(k, n) {
		return false
	}

	if len(n.Body) != 1 {
		return false
	}

	stmt := n.Body[0] // only stmt in body
	if stmt == nil || stmt.Op() != ir.ODELETE {
		return false
	}

	m := n.X
	if delete := stmt.(*ir.CallExpr); !syncgoCtx.Typecheck.IR.SameSafeExpr(delete.Args[0], m) || !syncgoCtx.Typecheck.IR.SameSafeExpr(delete.Args[1], k) {
		return false
	}

	// Keys where equality is not reflexive can not be deleted from maps.
	if !syncgoCtx.Typecheck.IR.Types.IsReflexive(t.Key()) {
		return false
	}

	return true
}

// mapRangeClear constructs a call to runtime.mapclear for the map range idiom.
func (syncgoCtx *Context) mapRangeClear(nrange *ir.RangeStmt) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	m := nrange.X
	origPos := syncgoCtx.Typecheck.IR.SetPos(m)
	defer func() { syncgoCtx.Typecheck.IR.Types.Pos = origPos }()

	return syncgoCtx.mapClear(m, syncgoCtx.Noder.ReflectData.RangeMapRType(syncgoCtx.Typecheck.IR.Types.Pos, nrange))
}

// mapClear constructs a call to runtime.mapclear for the map m.
func (syncgoCtx *Context) mapClear(m, rtyp ir.Node) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	t := m.Type()

	// instantiate mapclear(typ *type, hmap map[any]any)
	fn := syncgoCtx.Typecheck.LookupRuntime("mapclear", t.Key(), t.Elem())
	n := syncgoCtx.mkcallstmt1(fn, rtyp, m)
	return syncgoCtx.Typecheck.Stmt(n)
}

// Lower n into runtime·memclr if possible, for
// fast zeroing of slices and arrays (issue 5373).
// Look for instances of
//
//	for i := range a {
//		a[i] = zero
//	}
//
// in which the evaluation of a is side-effect-free.
//
// Parameters are as in walkRange: "for v1, v2 = range a".
func (syncgoCtx *Context) arrayRangeClear(loop *ir.RangeStmt, v1, v2, a ir.Node) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	if syncgoCtx.Typecheck.IR.Base.Flag.N != 0 || syncgoCtx.Typecheck.IR.Base.Flag.Cfg.Instrumenting {
		return nil
	}

	if v1 == nil || v2 != nil {
		return nil
	}

	if len(loop.Body) != 1 || loop.Body[0] == nil {
		return nil
	}

	stmt1 := loop.Body[0] // only stmt in body
	if stmt1.Op() != ir.OAS {
		return nil
	}
	stmt := stmt1.(*ir.AssignStmt)
	if stmt.X.Op() != ir.OINDEX {
		return nil
	}
	lhs := stmt.X.(*ir.IndexExpr)
	x := lhs.X

	// Get constant number of iterations for int and array cases.
	n := int64(-1)
	if ir.IsConst(a, constant.Int) {
		n = syncgoCtx.Typecheck.IR.Int64Val(a)
	} else if a.Type().IsArray() {
		n = a.Type().NumElem()
	} else if a.Type().IsPtr() && a.Type().Elem().IsArray() {
		n = a.Type().Elem().NumElem()
	}

	if n >= 0 {
		// Int/Array case.
		if !x.Type().IsArray() {
			return nil
		}
		if x.Type().NumElem() != n {
			return nil
		}
	} else {
		// Slice case.
		if !syncgoCtx.Typecheck.IR.SameSafeExpr(x, a) {
			return nil
		}
	}

	if !syncgoCtx.Typecheck.IR.SameSafeExpr(lhs.Index, v1) {
		return nil
	}

	if !ir.IsZero(stmt.Y) {
		return nil
	}

	return syncgoCtx.arrayClear(stmt.Pos(), x, loop)
}

// arrayClear constructs a call to runtime.memclr for fast zeroing of slices and arrays.
func (syncgoCtx *Context) arrayClear(wbPos src.XPos, a ir.Node, nrange *ir.RangeStmt) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	elemsize := typecheck.RangeExprType(a.Type()).Elem().Size()
	if elemsize <= 0 {
		return nil
	}

	// Convert to
	// if ln := len(a); ln != 0 {
	// 	hp = &a[0]
	// 	hn = len(a)*sizeof(elem(a))
	// 	memclr{NoHeap,Has}Pointers(hp, hn)
	// 	i = ln - 1
	// }
	n := syncgoCtx.Typecheck.IR.NewIfStmt(syncgoCtx.Typecheck.IR.Types.Pos, nil, nil, nil)
	ln := syncgoCtx.Typecheck.TempAt(syncgoCtx.Typecheck.IR.Types.Pos, syncgoCtx.Typecheck.IR.CurFunc, syncgoCtx.Typecheck.IR.Types.Types[types.TINT])
	as := syncgoCtx.Typecheck.IR.NewAssignStmt(syncgoCtx.Typecheck.IR.Types.Pos, ln, syncgoCtx.Typecheck.IR.NewUnaryExpr(syncgoCtx.Typecheck.IR.Types.Pos, ir.OLEN, a))
	n.PtrInit().Append(syncgoCtx.Typecheck.Stmt(as))
	n.Cond = syncgoCtx.Typecheck.IR.NewBinaryExpr(syncgoCtx.Typecheck.IR.Types.Pos, ir.ONE, ln, syncgoCtx.Typecheck.IR.NewInt(syncgoCtx.Typecheck.IR.Types.Pos, 0))

	// hp = &a[0]
	hp := syncgoCtx.Typecheck.TempAt(syncgoCtx.Typecheck.IR.Types.Pos, syncgoCtx.Typecheck.IR.CurFunc, syncgoCtx.Typecheck.IR.Types.Types[types.TUNSAFEPTR])

	ix := syncgoCtx.Typecheck.IR.NewIndexExpr(syncgoCtx.Typecheck.IR.Types.Pos, a, syncgoCtx.Typecheck.IR.NewInt(syncgoCtx.Typecheck.IR.Types.Pos, 0))
	ix.SetBounded(true)
	addr := syncgoCtx.Typecheck.ConvNop(syncgoCtx.Typecheck.NodAddr(ix), syncgoCtx.Typecheck.IR.Types.Types[types.TUNSAFEPTR])
	n.Body.Append(syncgoCtx.Typecheck.IR.NewAssignStmt(syncgoCtx.Typecheck.IR.Types.Pos, hp, addr))

	// hn = len(a) * sizeof(elem(a))
	hn := syncgoCtx.Typecheck.TempAt(syncgoCtx.Typecheck.IR.Types.Pos, syncgoCtx.Typecheck.IR.CurFunc, syncgoCtx.Typecheck.IR.Types.Types[types.TUINTPTR])
	mul := syncgoCtx.Typecheck.Conv(syncgoCtx.Typecheck.IR.NewBinaryExpr(syncgoCtx.Typecheck.IR.Types.Pos, ir.OMUL, ln, syncgoCtx.Typecheck.IR.NewInt(syncgoCtx.Typecheck.IR.Types.Pos, elemsize)), syncgoCtx.Typecheck.IR.Types.Types[types.TUINTPTR])
	n.Body.Append(syncgoCtx.Typecheck.IR.NewAssignStmt(syncgoCtx.Typecheck.IR.Types.Pos, hn, mul))

	var fn ir.Node
	if a.Type().Elem().HasPointers() {
		// memclrHasPointers(hp, hn)
		syncgoCtx.Typecheck.IR.CurFunc.SetWBPos(wbPos)
		fn = syncgoCtx.mkcallstmt("memclrHasPointers", hp, hn)
	} else {
		// memclrNoHeapPointers(hp, hn)
		fn = syncgoCtx.mkcallstmt("memclrNoHeapPointers", hp, hn)
	}

	n.Body.Append(fn)

	// For array range clear, also set "i = len(a) - 1"
	if nrange != nil {
		idx := syncgoCtx.Typecheck.IR.NewAssignStmt(syncgoCtx.Typecheck.IR.Types.Pos, nrange.Key, syncgoCtx.Typecheck.Conv(syncgoCtx.Typecheck.IR.NewBinaryExpr(syncgoCtx.Typecheck.IR.Types.Pos, ir.OSUB, ln, syncgoCtx.Typecheck.IR.NewInt(syncgoCtx.Typecheck.IR.Types.Pos, 1)), nrange.Key.Type()))
		n.Body.Append(idx)
	}

	n.Cond = syncgoCtx.Typecheck.Expr(n.Cond)
	n.Cond = syncgoCtx.Typecheck.DefaultLit(n.Cond, nil)
	syncgoCtx.Typecheck.Stmts(n.Body)
	return syncgoCtx.walkStmt(n)
}
